//! The strict fixture checks of `fixtures_strict.rs`, run through the
//! `&'static GrammarSet` tables generated by `rexi-schema-gen` instead of tables
//! compiled at runtime. Passing means the generated statics produce output
//! byte-identical to the runtime-compiled tables (both equal EXIficient's bytes).

mod common;

use rexi_core::GrammarSet;
use rexi_tests::{Case, generated};

fn statics(case: &Case) -> &'static GrammarSet<'static> {
    generated::by_case(&case.name).unwrap_or_else(|| {
        panic!(
            "{}: no generated tables; run scripts/gen-tables.sh",
            case.name
        )
    })
}

#[test]
fn encode_matches_exificient() {
    common::encode_matches_exificient(statics);
}

#[test]
fn decode_matches_oracle_events() {
    common::decode_matches_oracle_events(statics);
}

#[test]
fn reencode_decoded_events_round_trips() {
    common::reencode_decoded_events_round_trips(statics);
}

#[test]
fn exipd_accepts_rexi_output() {
    common::exipd_accepts_rexi_output(statics);
}
